ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
AYLAR = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
def w3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(('' if h == 1 else ONES[h] + ' ') + 'yüz')
    if t:
        s.append(TENS[t])
    if o:
        s.append(ONES[o])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, nm in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append(('' if (q == 1 and nm == 'bin') else w3(q) + ' ') + nm)
    if n:
        parts.append(w3(n))
    return ' '.join(parts)
